const state = $('Route Claude Judgement Result').item.json;
const payload = $json;
let raw = '';
if (typeof payload.response === 'string') raw = payload.response;
else if (typeof payload === 'string') raw = payload;
else if (typeof payload.data === 'string') raw = payload.data;
else if (typeof payload.body === 'string') raw = payload.body;
else raw = JSON.stringify(payload);
