const candidate = state.candidate;
const updatedResearch = {...research, recommended_topic: candidate};
return [{json: {worth_it: worthIt, topic_match: topicMatch, reason, failure_mode: failureMode, research: updatedResearch, candidate, judgement_queue: state.judgement_queue, judgement_index: state.judgement_index}}];

const state = $('Normalize Judgement Verdict').item.json;
const queue = Array.isArray(state.judgement_queue) ? state.judgement_queue : [];
const nextIndex = Number(state.judgement_index ?? 0) + 1;
