const research = $json.research;
const topic = research?.recommended_topic;
if (!topic) throw new Error('SEO_MISSING_RECOMMENDED_TOPIC');
const incoming = topic.seo_brief ?? {};
const toolName = String(topic.tool_name ?? topic.topic ?? 'AI developer tool').trim();
const primaryKeyword = String(incoming.primary_keyword ?? `${toolName} for developers`).trim();
const relatedKeywords = [...new Set((Array.isArray(incoming.related_keywords) ? incoming.related_keywords : []).map((value) => String(value).trim()).filter(Boolean))].slice(0, 8);
const titleOptions = [...new Set((Array.isArray(incoming.title_options) ? incoming.title_options : []).map((value) => String(value).trim()).filter(Boolean))].slice(0, 5);
if (!titleOptions.length) titleOptions.push(`${toolName}: the developer workflow it improves`);
const hashtags = [...new Set((Array.isArray(incoming.hashtags) ? incoming.hashtags : []).map((value) => `#${String(value).replace(/^#/, '').replace(/[^A-Za-z0-9_]/g, '')}`).filter((value) => value.length > 1))].slice(0, 8);
for (const fallback of ['#AITools', '#DeveloperTools', '#Coding']) { if (hashtags.length >= 5) break; if (!hashtags.includes(fallback)) hashtags.push(fallback); }
const seoBrief = { primary_keyword: primaryKeyword, related_keywords: relatedKeywords, search_intent: incoming.search_intent ?? 'informational', title_options: titleOptions, description: String(incoming.description ?? topic.one_line_value ?? topic.why_it_matters ?? '').trim(), hashtags };
research.recommended_topic.seo_brief = seoBrief;
return [{ json: { ...$json, research, seo_brief: seoBrief } }];

const research = $items('Finalize SEO Brief')[0]?.json?.research;
if (!research?.recommended_topic) throw new Error('SCRIPT_MISSING_RESEARCH');
const topic = research.recommended_topic;
const prompt = `Write a clean, evidence-based dialogue for a 10-15 second vertical video revealing ONE developer tip. Return exactly four short alternating turns, beginning with Peter.

This video is short on purpose -- every word must earn its place. Dialogue structure -- still an argument, not a briefing, just a fast one:
1. Peter opens with the hook: the single boldest, most surprising claim about the tip, stated in one short sentence of 10 words or fewer. This line is the entire reason someone keeps watching instead of scrolling, so it must land in the first 4-5 seconds with zero wind-up, greeting, or context-setting.
2. Stewie pushes back in one short sentence -- skeptical that this is really useful, or naming the obvious reason nobody bothers with it.
3. Peter delivers the payoff in one short sentence: the exact, concrete win (time saved, mistake avoided, friction removed) that answers Stewie's skepticism, using only facts from the research package.
4. Stewie delivers a short, genuine verdict in one short sentence -- concede the point with a final jab, or admit it's better than expected. Never a flat "okay, thanks."

Every turn is one short, complete, conversational sentence with simple grammar and a clear subject -- these are quick jabs, not explanations. Turn 0's 10-word hook limit is a hard requirement -- count the words before returning and shorten if it runs long. Total spoken words across all four turns must stay between 20 and 28 -- count them before returning. This is measured against real narration speed for this show (about 2 words per second), so a script anywhere near 40+ words runs 18-20+ seconds and will be rejected outright; staying near the low end of the range is safer than the high end. Peter is plain-spoken, confident, and mildly funny; Stewie is precise, skeptical, and cutting. They are arguing with each other, not narrating to the camera. Name the tip or tool early if it has one. Never include stage directions, headings, URLs, profanity, keyword stuffing, sentence fragments, or unsupported hype. Use only facts from the research package.

After writing the dialogue, plan 4-6 distinct visual cues. Every one of the four turns (turn_index 0 through 3) MUST appear in the visuals array at least once -- this is a hard requirement. Before returning, re-read your own four turns and check that turn_index 0, 1, 2, and 3 each appear at least once in visuals; if any turn is missing, add a cue for it before adding a second cue to a denser turn. Each cue must name an exact phrase spoken in its zero-based turn_index, a focused image-search query, kind logo or screenshot, a visual_purpose of identity, interface, mechanism, outcome, evidence, reaction, or context, and a source_url to the exact product, documentation, repository, or evidence page. Prefer official UI screenshots, GitHub README diagrams, code, terminal output, and readable product imagery. Stock images are allowed only for reaction or context and must never serve as evidence for the tip itself. Never request generic approval/review imagery, generic article headers, government documents, unrelated products, or repeated variants of the same artwork.

Return ONLY JSON: {"title":"","focus":"","turns":[{"speaker":"peter","text":""},{"speaker":"stewie","text":""},{"speaker":"peter","text":""},{"speaker":"stewie","text":""}],"visuals":[{"turn_index":0,"phrase":"exact spoken phrase","query":"tool name screenshot","kind":"screenshot","visual_purpose":"interface","source_url":"https://official-source-page"}]}
RECOMMENDED RESEARCH:
${JSON.stringify(topic)}`;
return [{json: {prompt, research, seo_brief: $items('Finalize SEO Brief')[0]?.json?.seo_brief}}];

const promptItem = $items('Build Dialogue Prompt')[0]?.json ?? {};
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const text = Array.isArray(body?.content) ? body.content.filter((block) => block?.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim() : '';
const errorType = String(body?.error?.type ?? body?.type ?? '').trim();
let dialogueValid = false;
if (statusCode >= 200 && statusCode < 300 && text) {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = String(fenced?.[1] ?? text).trim();
  try {
    const parsed = JSON.parse(candidate);
    const expected = ['peter', 'stewie', 'peter', 'stewie'];
    const turns = Array.isArray(parsed.turns) ? parsed.turns : [];
    const wordCount = turns.reduce((sum, turn) => sum + String(turn.text ?? '').trim().split(/\s+/).filter(Boolean).length, 0);
    dialogueValid = turns.length === 4 && turns.every((turn, index) => String(turn.speaker ?? '').toLowerCase().trim() === expected[index] && String(turn.text ?? '').trim()) && wordCount >= 14 && wordCount <= 37;
  } catch {}
}
if (dialogueValid) {
  return [{json: {use_qwen_fallback: false, response: text, dialogue_provider: 'anthropic', dialogue_model: body?.model ?? 'claude', prompt: promptItem.prompt, research: promptItem.research, seo_brief: promptItem.seo_brief}}];
}
const fallbackReason = statusCode < 200 || statusCode >= 300 ? `${statusCode}_${errorType || 'http_error'}` : text ? 'invalid_dialogue' : 'empty_response';
return [{json: {use_qwen_fallback: true, prompt: promptItem.prompt, research: promptItem.research, seo_brief: promptItem.seo_brief, dialogue_provider: 'qwen-fallback', fallback_reason: fallbackReason}}];

const topicSlug = $('When Executed by Wrapper').item.json.topicSlug;
const payload = $json;
let raw = '';
if (typeof payload === 'string') raw = payload;
else if (typeof payload.data === 'string') raw = payload.data;
else if (typeof payload.body === 'string') raw = payload.body;
else if (typeof payload.response === 'string') raw = payload.response;
else raw = JSON.stringify(payload);
