  }
  if (isNdjson && chunks.every((chunk) => typeof chunk.response === 'string')) generated = chunks.map((chunk) => chunk.response).join('');
}
const fenced = generated.match(/```(?:json)?\s*([\s\S]*?)```/i);
const candidate = String(fenced?.[1] ?? generated).trim();
let dialoguePackage;
const end = candidate.lastIndexOf('}');
for (const start of [0, ...[...candidate.matchAll(/\{/g)].map((match) => match.index)]) {
  if (end < start) continue;
  try {
    const parsed = JSON.parse(candidate.slice(start, end + 1));
    if (Array.isArray(parsed.turns)) { dialoguePackage = parsed; break; }
  } catch {}
}
if (!dialoguePackage || dialoguePackage.turns.length !== 4) throw new Error('DIALOGUE_REQUIRES_FOUR_TURNS');
const expected = ['peter', 'stewie', 'peter', 'stewie'];
const dialogue = dialoguePackage.turns.map((turn, index) => {
  const speaker = String(turn.speaker ?? '').toLowerCase().trim();
  if (speaker !== expected[index]) throw new Error(`DIALOGUE_SPEAKER_ORDER:${index}`);
  const text = String(turn.text ?? '').replace(/\s+/g, ' ').trim();
  if (!text) throw new Error(`DIALOGUE_EMPTY_TURN:${index}`);
  return {speaker, text, turn_index: index, audio_path: `/media/${topicSlug}-tips-dialogue-${index}-${speaker}.wav`};
});
const wordCount = dialogue.reduce((sum, turn) => sum + turn.text.split(/\s+/).length, 0);
