const promptItem = $items('Build Instagram Caption Prompt')[0]?.json ?? {};
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const text = Array.isArray(body?.content) ? body.content.filter((block) => block?.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim() : '';
let caption; let captionSource = 'seo_fallback';
if (statusCode >= 200 && statusCode < 300 && text) {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = String(fenced?.[1] ?? text).trim();
  try {
    const parsed = JSON.parse(candidate);
    const parsedCaption = String(parsed.caption ?? '').trim();
    const hashtags = Array.isArray(parsed.hashtags) ? parsed.hashtags.map((tag) => String(tag).trim()).filter(Boolean) : [];
    if (parsedCaption && hashtags.length) { caption = `${parsedCaption}\n\n${hashtags.join(' ')}`; captionSource = 'claude'; }
  } catch {}
}
if (!caption) {
  const seoBrief = promptItem.seo_brief ?? {};
  const description = String(seoBrief.description ?? '').trim();
  const hashtags = Array.isArray(seoBrief.hashtags) ? seoBrief.hashtags : [];
  caption = [description, hashtags.join(' ')].filter(Boolean).join('\n\n');
}
if (!caption) throw new Error('INSTAGRAM_CAPTION_UNAVAILABLE');
return [{ json: { caption, captionSource, outputLocation: promptItem.outputLocation } }];

